/* Merchant/vendor display names (from FF_DATA) mapped to their Simple Icons
   slug. Names not listed here have no verified brand asset available and
   fall back to a generic glyph rather than an invented mark. */
const MERCHANT_ICON_MAP = {
  "Figma": "figma",
  "Lyft": "lyft",
  "Marriott": "marriott",
  "Marriott Austin": "marriott",
  "Marriott SF": "marriott",
  "Notion": "notion",
  "United Airlines": "unitedairlines",
  "Webflow": "webflow",
  "Google Cloud": "googlecloud",
  "Google Chat": "googlechat",
  "Xero": "xero",
  "Wise": "wise",
  "Starbucks": "starbucks",
  "Udemy": "udemy",
  "Ticketmaster": "ticketmaster",
  "ADP": "adp",
  "Chase": "chase",
};

const MerchantIcon = ({ name, size = 16, style = {} }) => {
  const key = MERCHANT_ICON_MAP[name];
  if (!key) return <Icon name="storefront" size={size} style={style}/>;
  return <BrandIcon name={key} size={size} style={style}/>;
};

const BrandIcon = ({ name, size = 16, style = {} }) => {
  if (name === "google") {
    return (
      <svg width={size} height={size} viewBox="0 0 18 18" style={{ flexShrink: 0, ...style }} aria-hidden="true">
        <path fill="#4285F4" d="M17.64 9.2045c0-.6381-.0573-1.2518-.1636-1.8409H9v3.4814h4.8436c-.2086 1.125-.8427 2.0782-1.7955 2.7164v2.2581h2.9087c1.7018-1.5668 2.6836-3.874 2.6836-6.615z"/>
        <path fill="#34A853" d="M9 18c2.43 0 4.4673-.806 5.9564-2.1805l-2.9087-2.2581c-.806.5399-1.8368.8618-3.0477.8618-2.3436 0-4.3282-1.5831-5.036-3.7104H.9573v2.3318C2.4382 15.9832 5.4818 18 9 18z"/>
        <path fill="#FBBC05" d="M3.964 10.71c-.18-.5399-.2822-1.1155-.2822-1.71s.1023-1.1701.2822-1.71V4.9582H.9573C.3477 6.1732 0 7.5477 0 9c0 1.4523.3477 2.8268.9573 4.0418L3.964 10.71z"/>
        <path fill="#EA4335" d="M9 3.5795c1.3214 0 2.5077.4541 3.4405 1.346l2.5813-2.5814C13.4632.8918 11.4259 0 9 0 5.4818 0 2.4382 2.0168.9573 4.9582L3.964 7.29C4.6718 5.1627 6.6564 3.5795 9 3.5795z"/>
      </svg>
    );
  }
  if (name === "microsoft") {
    return (
      <svg width={size} height={size} viewBox="0 0 21 21" style={{ flexShrink: 0, ...style }} aria-hidden="true">
        <rect x="1" y="1" width="9" height="9" fill="#F25022"/>
        <rect x="11" y="1" width="9" height="9" fill="#7FBA00"/>
        <rect x="1" y="11" width="9" height="9" fill="#00A4EF"/>
        <rect x="11" y="11" width="9" height="9" fill="#FFB900"/>
      </svg>
    );
  }
  const icon = BRAND_ICON_PATHS[name];
  if (!icon) return null;
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill={icon.color} style={{ flexShrink: 0, ...style }} aria-hidden="true">
      <path d={icon.d}/>
    </svg>
  );
};

const Money = ({ value, signed = false, className = "" }) => {
  const sign = signed && value > 0 ? "+" : "";
  const fmt = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 2 });
  return <span className={`ff-tnum ${className}`}>{sign}{fmt.format(value)}</span>;
};

/* One date format everywhere: ISO in, "May 22, 2026" out. */
const fmtDate = (iso) => new Date(iso + "T00:00:00").toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });

/* Status → semantic group + icon. Every status string used anywhere in the
   app (and every label named in the design-system brief, whether or not
   FinFlow's mock data currently produces it) resolves through this one
   table — no component picks its own color or icon. Group = which of the
   seven --ff-status-* token sets renders; icon/label are per-status. */
const STATUS_MAP = {
  // success
  approved:      { group: "success", label: "Approved",  icon: "check-circle" },
  paid:          { group: "success", label: "Paid",      icon: "check-circle" },
  completed:     { group: "success", label: "Completed", icon: "check-circle" },
  active:        { group: "success", label: "Active",    icon: "check-circle" },
  connected:     { group: "success", label: "Connected", icon: "check-circle" },
  // warning
  pending:          { group: "warning", label: "Pending",         icon: "clock" },
  "awaiting-review":{ group: "warning", label: "Awaiting review", icon: "clock" },
  waiting:          { group: "warning", label: "Waiting",         icon: "clock" },
  "in-progress":    { group: "warning", label: "In progress",     icon: "clock" },
  scheduled:        { group: "warning", label: "Scheduled",       icon: "clock" },
  // info
  submitted:      { group: "info", label: "Submitted",     icon: "file-text" },
  processing:     { group: "info", label: "Processing",    icon: "spinner-gap" },
  "policy-check": { group: "info", label: "Policy check",  icon: "shield-check" },
  "under-review": { group: "info", label: "Under review",  icon: "eye" },
  information:    { group: "info", label: "Information",   icon: "info" },
  available:      { group: "info", label: "Available",     icon: "info" },
  // review
  flagged:          { group: "review", label: "Flagged",        icon: "flag" },
  escalated:        { group: "review", label: "Escalated",      icon: "flag" },
  "manual-review":  { group: "review", label: "Manual review",  icon: "flag" },
  suspicious:       { group: "review", label: "Suspicious",     icon: "flag" },
  // action required
  "needs-info":       { group: "action", label: "Needs info",       icon: "warning-circle" },
  needs:               { group: "action", label: "Needs info",       icon: "warning-circle" },
  "missing-receipt":  { group: "action", label: "Missing receipt",  icon: "warning-circle" },
  "awaiting-user":    { group: "action", label: "Awaiting you",     icon: "warning-circle" },
  "requires-action":  { group: "action", label: "Requires action",  icon: "warning-circle" },
  // danger
  rejected:          { group: "danger", label: "Rejected",         icon: "x-circle" },
  failed:            { group: "danger", label: "Failed",           icon: "x-circle" },
  "over-cap":        { group: "danger", label: "Over cap",         icon: "warning" },
  over:               { group: "danger", label: "Over cap",         icon: "warning" },
  "policy-violation":{ group: "danger", label: "Policy violation", icon: "warning" },
  violate:            { group: "danger", label: "Policy violation", icon: "warning" },
  declined:          { group: "danger", label: "Declined",         icon: "x-circle" },
  // neutral
  draft:      { group: "neutral", label: "Draft",     icon: "circle" },
  archived:   { group: "neutral", label: "Archived",  icon: "archive" },
  cancelled:  { group: "neutral", label: "Cancelled", icon: "circle" },
  disabled:   { group: "neutral", label: "Disabled",  icon: "circle" },
  expired:    { group: "neutral", label: "Expired",   icon: "clock" },
  frozen:     { group: "neutral", label: "Frozen",    icon: "snowflake" },
  ok:         { group: "neutral", label: "OK",        icon: "check-circle" }
};

const StatusBadge = ({ status }) => {
  const m = STATUS_MAP[status] || { group: "neutral", label: status, icon: "circle" };
  return (
    <span className={`ff-badge ff-badge--${m.group}`}>
      <span className="ff-badge__icon"><Icon name={m.icon} size={12}/></span>
      {m.label}
    </span>
  );
};

/* One consistent headshot per person, keyed by full name — same photo
   everywhere that person appears. Names without a mapped photo fall back
   to the existing initials badge rather than a mismatched or invented image. */
const PERSON_PHOTOS = {
  "Marcus Stoinis":  "assets/avatars/marcus-stoinis.jpg",
  "Xavier Bartlett":  "assets/avatars/xavier-bartlett.jpg",
  "Corey Anderson":   "assets/avatars/corey-anderson.jpg",
  "Sam Richardson":   "assets/avatars/sam-richardson.jpg",
  "Jordan Lee":       "assets/avatars/jordan-lee.jpg",
  "Alex Morgan":      "assets/avatars/alex-morgan.jpg",
  "James Taylor":     "assets/avatars/james-taylor.jpg",
  "Jamie Smith":      "assets/avatars/jamie-smith.jpg",
  "Riley Meredith":   "assets/avatars/riley-meredith.jpg",
  "Sam Curran":       "assets/avatars/sam-curran.jpg",
};

const Avatar = ({ initials, name, size = "md", style = {} }) => {
  const cls = size === "lg" ? "ff-avatar ff-avatar--lg" : size === "xl" ? "ff-avatar ff-avatar--xl" : "ff-avatar";
  const photo = name && PERSON_PHOTOS[name];
  if (photo) {
    return (
      <span className={cls} style={{...style, padding: 0, overflow: 'hidden'}}>
        <img src={photo} alt={name} style={{width: '100%', height: '100%', objectFit: 'cover', borderRadius: 'inherit'}}/>
      </span>
    );
  }
  return <span className={cls} style={style}>{initials}</span>;
};

/* Pilot redesign: horizontal nav, no sidebar. Each role gets its 5-7
   highest-frequency destinations in the row itself; everything else lives
   behind "More" (opens the same ⌘K directory used for search) rather than
   cramming a 12-item sidebar into one row. */
const TOPNAV_ITEMS = {
  finance: [
    { id: "dashboard",  label: "Dashboard" },
    { id: "expenses",   label: "Expenses",      count: 14 },
    { id: "approvals",  label: "Approvals",     count: FF_PENDING },
    { id: "reimburse",  label: "Reimbursements" },
    { id: "reports",    label: "Reports" }
  ],
  manager: [
    { id: "dashboard-mgr", label: "Team overview" },
    { id: "approvals",     label: "Approvals", count: FF_PENDING },
    { id: "expenses",      label: "Team expenses" },
    { id: "reports",       label: "Reports" },
    { id: "budgets",       label: "Budgets" }
  ],
  employee: [
    { id: "dashboard-emp", label: "My spend" },
    { id: "new-expense",   label: "New expense" },
    { id: "my-expenses",   label: "My expenses" },
    { id: "my-cards",      label: "My cards" },
    { id: "my-reimburse",  label: "Reimbursements" }
  ]
};

/* Real product functionality, not a screen-jump list — the same set behind
   every role's "More" (per the IA: low-frequency destinations get identical
   treatment regardless of role, reachable by search or here, never buried
   per-role). Global ⌘K search is offered as its own explicit last item. */
const MORE_MENU_ITEMS = [
  { id: "cards",                 label: "Cards",          icon: "credit-card" },
  { id: "vendors",               label: "Vendors",        icon: "storefront" },
  { id: "settings-profile",      label: "Settings",      icon: "gear" },
  { id: "settings-policies",     label: "Policies",       icon: "scales" },
  { id: "settings-team",         label: "Team & roles",   icon: "users-three" },
  { id: "settings-integrations", label: "Integrations",   icon: "plugs" },
  { id: "audit",                 label: "Audit log",      icon: "scroll" },
  { id: "notif",                 label: "Notifications",  icon: "bell" },
  { id: "help",                  label: "Help",           icon: "question" },
];

const TopNav = ({ role, current, onNavigate, theme, onTheme, onRole, onSearchClick, onNotif }) => {
  const user = FF_DATA.me[role];
  const [moreOpen, setMoreOpen] = React.useState(false);
  const moreRef = React.useRef(null);
  React.useEffect(() => {
    if (!moreOpen) return;
    const onDocClick = (e) => { if (moreRef.current && !moreRef.current.contains(e.target)) setMoreOpen(false); };
    const onEsc = (e) => { if (e.key === "Escape") setMoreOpen(false); };
    document.addEventListener("mousedown", onDocClick);
    document.addEventListener("keydown", onEsc);
    return () => { document.removeEventListener("mousedown", onDocClick); document.removeEventListener("keydown", onEsc); };
  }, [moreOpen]);
  return (
    <header className="ff-topnav">
      <a href="#" className="ff-topnav__brand" onClick={e=>{e.preventDefault(); onSearchClick();}}>
        <BrandMark variant="mark" size={24}/>
        <BrandMark variant="wordmark" size={17}/>
      </a>
      <nav className="ff-topnav__items" aria-label="Primary">
        {TOPNAV_ITEMS[role].map(it => (
          <a key={it.id} href="#"
             aria-current={current === it.id ? "page" : undefined}
             onClick={(e)=>{e.preventDefault(); onNavigate(it.id);}}>
            {it.label}
            {it.count !== undefined && it.count > 0 && <span className="ff-topnav__count ff-tnum">{it.count}</span>}
          </a>
        ))}
        <div ref={moreRef} style={{position:'relative'}}>
          <a href="#" className="ff-topnav__more" aria-haspopup="menu" aria-expanded={moreOpen}
             onClick={(e)=>{e.preventDefault(); setMoreOpen(o => !o);}}>
            More <Icon name="caret-down" size={11}/>
          </a>
          {moreOpen && (
            <div role="menu" style={{
              position:'absolute', top:'calc(100% + 6px)', left:0, minWidth:240, zIndex:60,
              background:'var(--ff-card)', border:'1px solid var(--ff-border-strong)', borderRadius:'var(--ff-radius-lg)',
              boxShadow:'var(--ff-shadow-lg)', padding:6,
            }}>
              {MORE_MENU_ITEMS.map(it => (
                <a key={it.id} role="menuitem" href="#" className="ff-nav-item"
                   onClick={(e)=>{e.preventDefault(); setMoreOpen(false); onNavigate(it.id);}}>
                  <span className="ff-nav-item__icon"><Icon name={it.icon} size={16}/></span>
                  <span>{it.label}</span>
                </a>
              ))}
              <hr className="ff-divider" style={{margin:'6px 4px'}}/>
              <a role="menuitem" href="#" className="ff-nav-item"
                 onClick={(e)=>{e.preventDefault(); setMoreOpen(false); onSearchClick();}}>
                <span className="ff-nav-item__icon"><Icon name="magnifying-glass" size={16}/></span>
                <span>Search all screens</span>
                <span className="ff-nav-item__count">⌘K</span>
              </a>
            </div>
          )}
        </div>
      </nav>
      <div style={{flex:1}}/>
      <div className="ff-segmented ff-segmented--sm" role="tablist" aria-label="Viewing role">
        {[
          { id: "finance",  label: "Admin" },
          { id: "manager",  label: "Manager" },
          { id: "employee", label: "Employee" }
        ].map(r => (
          <button key={r.id} aria-pressed={role === r.id} onClick={() => onRole(r.id)}>{r.label}</button>
        ))}
      </div>
      <button className="ff-btn ff-btn--ghost ff-btn--icon" onClick={onSearchClick} aria-label="Search">
        <Icon name="magnifying-glass" size={16}/>
      </button>
      <button className="ff-btn ff-btn--ghost ff-btn--icon" onClick={onTheme} aria-label="Toggle theme">
        <Icon name={theme === "dark" ? "sun" : "moon"} size={16}/>
      </button>
      <button className="ff-btn ff-btn--ghost ff-btn--icon" onClick={onNotif} aria-label="Notifications" style={{position:'relative'}}>
        <Icon name="bell" size={16}/>
        <span style={{position:'absolute', top:6, right:6, width:6, height:6, background:'var(--ff-rejected)', borderRadius:999}}/>
      </button>
      <div className="ff-topnav__profile">
        <Avatar initials={user.initials} name={user.name} style={{width:30, height:30, fontSize:12}}/>
        <div style={{minWidth:0}}>
          <div className="ff-topnav__profile-name">{user.name}</div>
          <div className="ff-topnav__profile-title">{user.title}</div>
        </div>
      </div>
    </header>
  );
};

/* Refresh button — shared across dashboards/expenses/approvals. Tracks "last synced" locally. */
const RefreshButton = () => {
  const [spinning, setSpinning] = React.useState(false);
  const [synced, setSynced] = React.useState("2m ago");
  const onClick = () => {
    setSpinning(true);
    setTimeout(() => { setSpinning(false); setSynced("just now"); }, 500);
  };
  return (
    <button className="ff-btn ff-btn--ghost" onClick={onClick}>
      <Icon name="arrows-clockwise" size={14} style={{transform: spinning ? 'rotate(360deg)' : 'rotate(0deg)', transition: 'transform 0.5s var(--ff-ease)'}}/>
      Last synced {synced}
    </button>
  );
};

/* Density toggle — shared. Parent owns the boolean, this is just the button. */
const DensityToggle = ({ compact, onToggle }) => (
  <button className="ff-btn ff-btn--ghost" onClick={onToggle} aria-pressed={compact}>
    <Icon name={compact ? "rows" : "list"} size={14}/> {compact ? "Compact" : "Comfortable"}
  </button>
);

/* PageHead — title + actions */
const PageHead = ({ eyebrow, title, sub, actions, children }) => (
  <div className="ff-page__head">
    <div>
      {eyebrow && <div className="ff-eyebrow" style={{marginBottom:8}}>{eyebrow}</div>}
      <h1 className="ff-page__title">{title}</h1>
      {sub && <div className="ff-page__sub">{sub}</div>}
      {children}
    </div>
    <div className="ff-row" style={{gap:8}}>{actions}</div>
  </div>
);

/* KPI tile */
const KpiTile = ({ label, value, delta, trend, spark, hero = false }) => (
  <div className={hero ? "ff-kpi ff-kpi--hero" : "ff-kpi"}>
    <div className="ff-kpi__label">{label}</div>
    <div className="ff-kpi__value" style={hero ? {fontSize:40} : undefined}>{value}</div>
    <div className="ff-row" style={{justifyContent:'space-between'}}>
      <div className={`ff-kpi__delta ff-kpi__delta--${trend === "up" ? "up" : trend === "down" ? "down" : ""}`}>
        {trend === "up" && <Icon name="trend-up" size={12}/>}
        {trend === "down" && <Icon name="trend-down" size={12}/>}
        {delta}
      </div>
      {spark && <Sparkline data={spark} width={80} height={28}/>}
    </div>
  </div>
);

/* Inline stat item/row — label/value/delta, no card. Shared by every screen
   that needs a compact stat strip instead of a KPI-card grid (dashboards,
   reports, vendor/reimbursement detail). Consolidates what had drifted into
   five separately hand-rolled copies (20/22/26px values, 28/32px gaps) into
   one definition; delta reuses the same .ff-kpi__delta tokens KpiTile and
   badges already use, instead of each call site picking its own color. */
const StatItem = ({ label, value, delta, trend }) => (
  <div>
    <div className="ff-eyebrow">{label}</div>
    <div className="ff-row" style={{gap:8, marginTop:3}}>
      <span style={{fontSize:22, fontWeight:600, letterSpacing:'-0.015em'}} className="ff-tnum">{value}</span>
      {delta && <span className={`ff-kpi__delta ff-kpi__delta--${trend === "up" ? "up" : trend === "down" ? "down" : ""}`} style={{fontSize:12}}>{delta}</span>}
    </div>
  </div>
);
const StatRow = ({ items, style = {} }) => (
  <div className="ff-row" style={{gap:32, flexWrap:'wrap', ...style}}>
    {items.map((it, i) => <StatItem key={i} {...it}/>)}
  </div>
);

const Card = ({ title, action, children, padded = true, style = {} }) => (
  <section className="ff-card" style={style}>
    {(title || action) && (
      <header className="ff-card__head">
        <div className="ff-card__title">{title}</div>
        {action}
      </header>
    )}
    <div style={{padding: padded ? 20 : 0, overflowX: 'auto'}}>{children}</div>
  </section>
);

/* Category tag — a colored dot + text, for a category column that isn't a
   status (so it shouldn't pull StatusBadge's visual weight). Color comes
   from the category's own `color` field in FF_DATA (already the same
   --ff-chart-N token category-breakdown charts use for that category), not
   a separately hand-picked hue — "Software" is the same color as a dot here,
   a bar in a chart, or a dashboard legend swatch. Shared so every table with
   a category column (Vendors, Expenses) renders it identically. */
const CategoryTag = ({ color, name }) => (
  <span className="ff-row" style={{gap:7}}>
    <span style={{width:7, height:7, borderRadius:999, background:color, flexShrink:0}}/>
    {name}
  </span>
);

/* Empty state — shared so every list screen (Vendors, Reimbursements,
   Approval history, Audit log, Cards) renders the same thing when its data
   is empty, instead of a bare table header over nothing. Same visual
   language as the dedicated empty-state gallery screen, just without
   forcing a bordered Card around it, so it sits on the page like the
   borderless tables it replaces. */
const EmptyState = ({ icon, title, body, actions }) => (
  <div style={{display:'flex', alignItems:'center', justifyContent:'center', minHeight:'40vh'}}>
    <div className="ff-empty" style={{maxWidth:420}}>
      <div className="ff-empty__icon"><Icon name={icon} size={24}/></div>
      <div className="ff-empty__title">{title}</div>
      <div className="ff-empty__body">{body}</div>
      {actions && <div className="ff-row" style={{marginTop:12, gap:8, justifyContent:'center'}}>{actions}</div>}
    </div>
  </div>
);

/* Filter chip row */
const ChipBar = ({ items, value, onChange }) => (
  <div className="ff-row" style={{flexWrap:'wrap'}}>
    {items.map(it => (
      <button key={it.id} className="ff-chip" aria-pressed={value === it.id} onClick={() => onChange(it.id)}>
        {it.label}{it.count !== undefined && <span style={{color:'var(--ff-fg-muted)'}}>· {it.count}</span>}
      </button>
    ))}
  </div>
);

Object.assign(window, { Icon, BrandIcon, Money, fmtDate, StatusBadge, Avatar, TopNav, PageHead, KpiTile, StatItem, StatRow, Card, CategoryTag, EmptyState, ChipBar, RefreshButton, DensityToggle, ffGo, FF_PENDING });
